import {GameEngine} from './engine.js';
export class Multiplayer{
 constructor({onState,onMessage,onDisconnect}){this.onState=onState;this.onMessage=onMessage;this.onDisconnect=onDisconnect;this.room=null;this.engine=null;this.send=null;this.timer=null;this.isHost=false;this.selfId=null;this.code='';this.closed=false;this.lastHeard=0;this.peerHello=new Map()}
 async connect({host,code,name,level=1}){const {joinRoom,selfId}=await import('./vendor/trystero-mqtt.js');this.selfId=selfId;this.isHost=host;this.name=name;this.closed=false;let key;if(host){key=Array.from(crypto.getRandomValues(new Uint8Array(6)),n=>'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[n%32]).join('');this.hostId=selfId;this.code=key+'~'+selfId;this.engine=new GameEngine(level);this.engine.add(selfId,name)}else{let parts=String(code).trim().split('~');if(parts.length!==2||!parts[0].match(/^[A-Z2-9]{6}$/)||!parts[1].match(/^[A-Za-z0-9_-]{8,80}$/))throw Error('Kode ruang tidak valid. Salin seluruh kode dari host.');key=parts[0];this.hostId=parts[1];this.code=code.trim();if(this.hostId===selfId)throw Error('Gunakan browser atau perangkat lain untuk bergabung ke ruangmu sendiri.')}
this.room=joinRoom({appId:'wheres-my-pet-maple-v2',password:this.code},key);const [send,get]=this.room.makeAction('wmp-v2');this.send=send;get((data,peer)=>this.receive(data,peer));this.room.onPeerJoin(peer=>{if(!host&&peer===this.hostId)send({type:'hello',name:this.name},peer);if(host)this.onMessage('Koneksi pemain baru terdeteksi…')});this.room.onPeerLeave(peer=>{if(host){this.engine.remove(peer);this.broadcast()}else if(peer===this.hostId){this.onDisconnect('Host meninggalkan ruang. Sesi berakhir; kamu bisa melanjutkan mode solo.');this.leave()}});this.lastHeard=Date.now();this.timer=setInterval(()=>{if(this.closed)return;if(host){this.engine.tick();this.broadcast()}else if(Date.now()-this.lastHeard>25000){this.onMessage('Belum terhubung ke host. Pastikan host tetap membuka game; jaringan harus mengizinkan WebRTC.');this.lastHeard=Date.now()}},200);if(host)this.broadcast();return this.code}
 receive(data,peer){if(!data||typeof data.type!=='string')return;if(this.isHost){let now=Date.now();if(data.type==='hello'){let last=this.peerHello.get(peer)||0;if(now-last<2000)return;this.peerHello.set(peer,now);let result=this.engine.add(peer,data.name,now);this.send(result.ok?{type:'welcome'}:{type:'reject',message:result.error},peer);this.broadcast();return}if(!this.engine.players[peer])return;if(data.type==='pose')this.engine.pose(peer,data.position||{},now);if(data.type==='action'){let result=this.engine.act(peer,data.action,now);if(!result.ok)this.send({type:'notice',message:result.error},peer);this.broadcast()}}else if(peer===this.hostId){this.lastHeard=Date.now();if(data.type==='state'&&data.state?.version===2&&data.state.players?.[this.selfId])this.onState(data.state,this.selfId);if(data.type==='reject'){this.onDisconnect(data.message||'Ruang tidak dapat dimasuki.');this.leave()}if(data.type==='notice')this.onMessage(data.message)}}
 broadcast(){if(!this.engine)return;let state=JSON.parse(JSON.stringify(this.engine.snapshot()));this.onState(state,this.selfId);let ids=Object.keys(this.engine.players).filter(id=>id!==this.selfId);if(ids.length)this.send({type:'state',state},ids).catch(()=>{})}
 action(action){if(this.isHost){let r=this.engine.act(this.selfId,action);if(!r.ok)this.onMessage(r.error);this.broadcast()}else this.send?.({type:'action',action},this.hostId).catch(()=>this.onMessage('Koneksi terputus.'))}
 pose(position){if(this.isHost)this.engine.pose(this.selfId,position,Date.now());else this.send?.({type:'pose',position},this.hostId).catch(()=>{})}
 reset(level){if(!this.isHost)return;this.engine.reset(level,Date.now());this.broadcast()}
 leave(){this.closed=true;clearInterval(this.timer);this.room?.leave();this.room=null;this.send=null}
}
